const $ = s => root.querySelector(s);
const input = $('#lex-input'), keyInput = $('#lex-key'), remember = $('#lex-remember');
const output = $('.lex-output'), status = $('.lex-status'), configStatus = $('.lex-config-status');
const run = $('[data-action="run"]'), stop = $('[data-action="stop"]'), copy = $('[data-action="copy"]'), speak = $('[data-action="speak"]');
const settings = $('.lex-settings'), model = $('#lex-model'), source = $('#lex-source'), target = $('#lex-target'), style = $('#lex-style');
const KEY = 'codex-english-desk-key-v1', MODEL = 'codex-english-desk-model-v1', HISTORY = 'codex-english-desk-history-v1', VOCAB = 'codex-english-desk-vocabulary-v1';
let mode = 'translate', activeKey = '', busy = false, serial = 0, disposed = false, recent = [], current = null, pendingTimer = null;
const timers = new Set();
let vocabulary = [], settingsExpanded = false;
const saveWord = $('[data-action="save-word"]'), vocabSearch = $('[data-ui="vocab-search"]');
function later(fn, ms) { const t = setTimeout(() => { timers.delete(t); fn(); }, ms); timers.add(t); return t; }
function text(s, error = false, config = false) { const el = config ? configStatus : status; el.textContent = s; el.dataset.error = String(error); }
function read(name) { try { return localStorage.getItem(name); } catch (_) { return null; } }
function remove(name) { try { localStorage.removeItem(name); return true; } catch (_) { return false; } }
function write(name, value) { try { localStorage.setItem(name, value); return true; } catch (_) { return false; } }
function el(tag, cls, value) { const n = document.createElement(tag); if (cls) n.className = cls; if (value !== undefined) n.textContent = String(value); return n; }
function syncSettings() {
 settings.hidden = !!activeKey && !settingsExpanded;
 settings.open = !activeKey || settingsExpanded;
 $('[data-action="settings"]').setAttribute('aria-expanded', String(!settings.hidden && settings.open));
}
function keyBadge() { syncSettings(); $('[data-ui="key-status"]').textContent = activeKey ? (remember.checked ? 'Key 已配置 · 本地记住' : 'Key 已配置 · 当前页面') : '尚未设置 API Key'; }
function applySettings() {
 const value = keyInput.value.trim();
 if (!value || /\s/.test(value)) { text('请输入有效的 API Key，不要包含空格或换行。', true, true); keyInput.focus(); return false; }
 if (remember.checked) {
  if (!write(KEY, value)) { remember.checked = false; activeKey = value; keyBadge(); text('本地存储不可用，Key 仅在当前页面使用。', true, true); return true; }
 } else if (!remove(KEY)) { text('无法删除已保存的 Key，请检查浏览器存储权限。', true, true); return false; }
 activeKey = value; write(MODEL, model.value); keyBadge();
 text(remember.checked ? '设置已应用，Key 已保存在此浏览器。' : '设置已应用，Key 仅在当前页面使用。', false, true); return true;
}
function setBusy(value) {
 busy = value; run.hidden = value; stop.hidden = !value; input.disabled = value;
 root.querySelectorAll('[data-mode],[data-example],.lex-direction select,.lex-direction button,#lex-style,[data-action="test"]').forEach(n => n.disabled = value);
 output.setAttribute('aria-busy', String(value));
}
function empty() {
 current = null; copy.disabled = true; speak.hidden = true; saveWord.hidden = true; output.replaceChildren();
 const box = el('div', 'lex-empty'), icon = el('div', 'lex-empty-symbol', mode === 'dictionary' ? 'Aa' : '文');
 icon.append(el('span', '', mode === 'dictionary' ? '词' : 'A'));
 box.append(icon, el('h2', '', mode === 'dictionary' ? '一个词，一片新天地' : '让语言，不再有距离'), el('p', '', mode === 'dictionary' ? '查询英文单词或短语，发现释义、例句与用法。' : '输入一段文字，译文将在这里呈现。'), el('span', 'lex-empty-tag', mode === 'dictionary' ? 'MEANING · CONTEXT · USAGE' : '中文 ⇄ English'));
 output.append(box); $('[data-ui="result-meta"]').textContent = '由 DeepSeek 生成 · 请结合语境判断'; $('[data-ui="result-extra"]').textContent = '';
}
function setMode(next) {
 if (busy) return;
 mode = ['translate','dictionary','vocabulary'].includes(next) ? next : 'translate';
 root.querySelectorAll('[role="tab"][data-mode]').forEach(n => { const selected = n.dataset.mode === mode; n.setAttribute('aria-selected', String(selected)); n.tabIndex = selected ? 0 : -1; });
 const isVocabulary = mode === 'vocabulary';
 $('#lex-workspace').hidden = isVocabulary; $('#lex-vocabulary').hidden = !isVocabulary;
 $('.lex-try').hidden = isVocabulary; $('.lex-recents').hidden = isVocabulary;
 text('');
 if (isVocabulary) { renderVocabulary(); return; }
 $('#lex-workspace').setAttribute('aria-labelledby', 'lex-tab-' + mode);
 $('.lex-direction').hidden = mode === 'dictionary'; $('.lex-style-wrap').hidden = mode === 'dictionary';
 $('[data-ui="result-title"]').textContent = mode === 'dictionary' ? '词典释义' : '译文';
 run.textContent = mode === 'dictionary' ? '查询单词 ↗' : '开始翻译 ↗';
 input.maxLength = mode === 'dictionary' ? 180 : 6000;
 if (input.value.length > input.maxLength) input.value = input.value.slice(0, input.maxLength);
 input.placeholder = mode === 'dictionary' ? '输入一个英文单词或短语…\n\n例如 serendipity / make a difference' : '输入英文或中文，开始一次轻松的翻译。\n\n也可以切换到词典，探索一个英文单词。';
 count(); empty(); text('');
}
function count() { $('[data-ui="count"]').textContent = input.value.length.toLocaleString() + ' / ' + input.maxLength.toLocaleString(); }
function section(title, content) { const s = el('section', 'lex-dict-section'); s.append(el('h3', '', title), content); return s; }
function render(item) {
 current = item; output.replaceChildren(); copy.disabled = false; speak.hidden = true; refreshSaveWord();
 if (item.kind === 'translate') { output.append(el('div', 'lex-translation', item.result)); }
 else {
  const d = item.result, heading = el('div', 'lex-word-head'), title = el('div');
  title.append(el('h2', '', d.word || item.query));
  if (d.phonetic) title.append(el('p', '', d.phonetic));
  heading.append(title, el('span', 'lex-ai-tag', 'AI 词典')); output.append(heading);
  const defs = el('div', 'lex-defs');
  (Array.isArray(d.meanings) ? d.meanings : []).slice(0, 8).forEach(m => {
   if (!m || typeof m.definition !== 'string') return;
   const row = el('div', 'lex-def'); row.append(el('span', 'lex-pos', m.pos || '释义'), el('span', '', m.definition)); defs.append(row);
  });
